-- MT2009_PLUS_GROWTH_PET_V1: System Zwierzat Domowych (server-patches/pety/README.md). GENERATED by
-- tools/pety/gen_pety_sql.py from tools/pety/pety_data.py - edit those, not this file. Run by apply.sh at every start;
-- idempotent. The one-time steps keep their marker in player.playerbot_migrations ('pety:...').
SET NAMES utf8mb4;

-- The pets (one row a pet; its id is socket 2 of its seal or of the Klatka Transportowa it travels in). state:
-- 1 in a seal, 2 in a cage, 3 an old-system pet waiting for its seal (given at the owner's next login).
CREATE TABLE IF NOT EXISTS player.growth_pet (
	id INT UNSIGNED NOT NULL PRIMARY KEY,
	owner_id INT UNSIGNED NOT NULL DEFAULT 0,
	vnum INT UNSIGNED NOT NULL DEFAULT 0,
	state TINYINT UNSIGNED NOT NULL DEFAULT 1,
	name VARBINARY(24) NOT NULL DEFAULT '',
	size TINYINT UNSIGNED NOT NULL DEFAULT 0,
	level SMALLINT UNSIGNED NOT NULL DEFAULT 1,
	level_step TINYINT UNSIGNED NOT NULL DEFAULT 0,
	evolution TINYINT UNSIGNED NOT NULL DEFAULT 1,
	type TINYINT UNSIGNED NOT NULL DEFAULT 0,
	hp INT UNSIGNED NOT NULL DEFAULT 0, sp INT UNSIGNED NOT NULL DEFAULT 0, def INT UNSIGNED NOT NULL DEFAULT 0,
	hp_apply INT UNSIGNED NOT NULL DEFAULT 0, sp_apply INT UNSIGNED NOT NULL DEFAULT 0,
	def_apply INT UNSIGNED NOT NULL DEFAULT 0, age_apply INT UNSIGNED NOT NULL DEFAULT 0,
	skill0_lock TINYINT UNSIGNED NOT NULL DEFAULT 1, skill0 TINYINT UNSIGNED NOT NULL DEFAULT 0,
	skill0_level TINYINT UNSIGNED NOT NULL DEFAULT 0,
	skill1_lock TINYINT UNSIGNED NOT NULL DEFAULT 1, skill1 TINYINT UNSIGNED NOT NULL DEFAULT 0,
	skill1_level TINYINT UNSIGNED NOT NULL DEFAULT 0,
	skill2_lock TINYINT UNSIGNED NOT NULL DEFAULT 1, skill2 TINYINT UNSIGNED NOT NULL DEFAULT 0,
	skill2_level TINYINT UNSIGNED NOT NULL DEFAULT 0,
	exp BIGINT UNSIGNED NOT NULL DEFAULT 0, item_exp BIGINT UNSIGNED NOT NULL DEFAULT 0,
	birthday INT UNSIGNED NOT NULL DEFAULT 0, end_time INT UNSIGNED NOT NULL DEFAULT 0,
	max_time INT UNSIGNED NOT NULL DEFAULT 0,
	type_known TINYINT UNSIGNED NOT NULL DEFAULT 0,
	champion_level TINYINT UNSIGNED NOT NULL DEFAULT 0, champion_exp BIGINT UNSIGNED NOT NULL DEFAULT 0,
	champion_item_exp BIGINT UNSIGNED NOT NULL DEFAULT 0,
	champ_res INT UNSIGNED NOT NULL DEFAULT 0, champ_block INT UNSIGNED NOT NULL DEFAULT 0,
	champ_prec INT UNSIGNED NOT NULL DEFAULT 0, champ_res_apply INT UNSIGNED NOT NULL DEFAULT 0,
	champ_block_apply INT UNSIGNED NOT NULL DEFAULT 0, champ_prec_apply INT UNSIGNED NOT NULL DEFAULT 0,
	pot0_egg INT UNSIGNED NOT NULL DEFAULT 0, pot0_skill TINYINT UNSIGNED NOT NULL DEFAULT 0,
	pot0_end INT UNSIGNED NOT NULL DEFAULT 0, pot1_egg INT UNSIGNED NOT NULL DEFAULT 0,
	pot1_skill TINYINT UNSIGNED NOT NULL DEFAULT 0, pot1_end INT UNSIGNED NOT NULL DEFAULT 0,
	updated TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
	KEY owner_state (owner_id, state)
) ENGINE=InnoDB DEFAULT CHARSET=cp1250;

-- The skill proto (the wiki's tables; read by the db core at boot and sent to every game core). pet_vnum 0 = every
-- species; a species row overrides it (its specialty). value_t1..t8 = the skill level 20 value at pet level 105
-- per pet type; level_curve = the values of skill levels 1..20 at pet level 105 without a specialty; grow_levels =
-- the pet levels at which a level-20 value grows by one unit (empty = continuously, 80 % at 81); activate = the
-- chance (%) of an auto skill by skill level; duration = tenths of a second by skill level.
CREATE TABLE IF NOT EXISTS player.growth_pet_skill_proto (
	pet_vnum INT UNSIGNED NOT NULL DEFAULT 0,
	skill_vnum TINYINT UNSIGNED NOT NULL,
	name VARBINARY(32) NOT NULL DEFAULT '',
	type ENUM('NONE','PASSIVE','AUTO') NOT NULL DEFAULT 'PASSIVE',
	cooldown INT UNSIGNED NOT NULL DEFAULT 0,
	point_on VARCHAR(64) NOT NULL DEFAULT '',
	unit VARCHAR(8) NOT NULL DEFAULT '%10',
	value_t1 INT UNSIGNED NOT NULL DEFAULT 0,
	value_t2 INT UNSIGNED NOT NULL DEFAULT 0,
	value_t3 INT UNSIGNED NOT NULL DEFAULT 0,
	value_t4 INT UNSIGNED NOT NULL DEFAULT 0,
	value_t5 INT UNSIGNED NOT NULL DEFAULT 0,
	value_t6 INT UNSIGNED NOT NULL DEFAULT 0,
	value_t7 INT UNSIGNED NOT NULL DEFAULT 0,
	value_t8 INT UNSIGNED NOT NULL DEFAULT 0,
	level_curve VARCHAR(160) NOT NULL DEFAULT '',
	grow_levels VARCHAR(160) NOT NULL DEFAULT '',
	activate VARCHAR(100) NOT NULL DEFAULT '',
	duration VARCHAR(100) NOT NULL DEFAULT '',
	PRIMARY KEY (pet_vnum, skill_vnum)
) ENGINE=InnoDB DEFAULT CHARSET=cp1250;

-- ---- One time: the old New Pet System (MT2009_PLUS_NEW_PET_V1, player.newpet_pet) -> growth pets ----------------
-- (the owner's decisions of 4 November 2026: species, name and level kept; the type rolled as at a hatching (the
-- game finalises a state-3 row when it hands out the seal); the skills are not carried over.) Every old pet item
-- in the bags, the storerooms, the shops (Ikarus), the item awards and the ItemShop becomes a wiki item (the
-- mapping: server-patches/pety/README.md). One transaction: all or nothing; the marker last.
DELIMITER //
BEGIN NOT ATOMIC
	DECLARE has_old INT DEFAULT 0;
	DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
	IF (SELECT COUNT(*) FROM player.playerbot_migrations WHERE name = 'pety:migracja_v1') = 0 THEN
		SELECT COUNT(*) INTO has_old FROM information_schema.TABLES WHERE TABLE_SCHEMA = 'player' AND TABLE_NAME = 'newpet_pet';
		START TRANSACTION;
		IF has_old > 0 THEN
			-- the pets: id 0x7F000000 + the old id, state 3 (a seal at the next login) or 2 (packed in a transporter)
			INSERT IGNORE INTO player.growth_pet (id, owner_id, vnum, state, name, level, evolution, type, birthday,
					end_time, max_time)
			SELECT 2130706432 + n.id, IF(n.packed, 0, n.pid), n.egg + 300, IF(n.packed, 2, 3), n.name, LEAST(GREATEST(n.level, 1), 105),
					CASE WHEN n.level >= 81 AND n.evolution >= 3 THEN 4 WHEN n.level >= 81 THEN 3 WHEN n.level >= 41 THEN 2 ELSE 1 END,
					0, IF(n.created > 0, n.created, UNIX_TIMESTAMP()), 0, 0
			FROM player.newpet_pet n WHERE n.egg BETWEEN 55401 AND 55414;
			-- a transporter with a pet (55007, socket0 = the old id) -> Klatka Transportowa with the pet (30 days)
			UPDATE player.item SET socket2 = IF(socket0 > 0, 2130706432 + socket0, 0), socket0 = IF(socket0 > 0, UNIX_TIMESTAMP() + 2592000, 0),
				socket1 = IF(socket0 > 0, UNIX_TIMESTAMP(), 0), vnum = 55002, count = 1 WHERE vnum = 55007;
			-- (player.newpet_pet stays as it was - nothing reads it any more; a backup of the old pets)
		END IF;
		-- the old items (counts multiplied where one old item is several new ones)
		UPDATE player.item SET vnum = 55009, count = count * 1 WHERE vnum = 55010;
		UPDATE player.item_award SET vnum = 55009, count = count * 1 WHERE vnum = 55010;
		UPDATE player.item SET vnum = 55009, count = count * 1 WHERE vnum = 55011;
		UPDATE player.item_award SET vnum = 55009, count = count * 1 WHERE vnum = 55011;
