		-- the eggs: 7 days from now (the wiki's egg life; the old ones had none)
		UPDATE player.item SET socket0 = UNIX_TIMESTAMP() + 604800 WHERE vnum BETWEEN 55401 AND 55414 AND socket0 < UNIX_TIMESTAMP();
		-- an empty Transporter Peta (55002) stays an empty Klatka Transportowa
		UPDATE player.item SET socket0 = 0, socket1 = 0, socket2 = 0 WHERE vnum = 55002 AND socket2 = 0;
		-- the ItemShop (in game): the old pet page lines go; the wiki's lines are added by apply.sh (ishop_once pety_*)
		DELETE FROM common.itemshop_items WHERE vnum BETWEEN 55000 AND 55999;
		-- (Kolo Losu: its source kola-src/przedmioty.json has the new vnums - the seed rewrites the wheel at every start)
